CREATE OR REPLACE FUNCTION fetch_user_by_username(username TEXT) RETURNS TABLE(id INT, username TEXT, email TEXT) AS $$
BEGIN
    RETURN QUERY EXECUTE 'SELECT * FROM public.users WHERE username = ' || quote_literal(username);
END;
$$ LANGUAGE plpgsql;

